defmodule PortfolioHermannWeb.UploadController do
  use PortfolioHermannWeb, :controller

  alias PortfolioHermann.Projects

  # Uploaded filenames are generated by the admin and deliberately restricted
  # here as well, so a URL can never traverse outside the persistent uploads dir.
  def show(conn, %{"filename" => filename}) do
    if Regex.match?(~r/\A[a-f0-9-]+\.(jpg|jpeg|png|gif|webp)\z/i, filename) do
      path = Path.join(Projects.uploads_dir(), filename)

      if File.regular?(path) do
        conn
        |> put_resp_content_type(MIME.from_path(path))
        |> put_resp_header("cache-control", "public, max-age=31536000, immutable")
        |> put_resp_header("x-content-type-options", "nosniff")
        |> send_file(200, path)
      else
        send_resp(conn, 404, "Not found")
      end
    else
      send_resp(conn, 404, "Not found")
    end
  end
end
